patches.new:
let A(skA, pkA, pkB) =
  new na;
  let enc = aenc(<pkA, na>, pkB) in
  let sig = sign(enc, skA) in
  let m = <sig, enc> in
  event Role('A');
  event Send(pkA, m);
  event Secret_A(na, pkB);
  out(m)

let B(skB, pkB, pkA) =
  in(m);
  let sig = fst(m) in
  let enc = snd(m) in
  if verify(sig, enc, pkA) = true then (
    let plain = adec(enc, skB) in
    let pk_recv = fst(plain) in
    let na = snd(plain) in
    if pk_recv = pkA then (
      event Role('B');
      event Recv(pkB, m);
      event Secret_B(na, pkB);
      event End()
    )
  )

process:
  new skA;
  new skB;
  let pkA = pk(skA) in
  let pkB = pk(skB) in
  ( !A(skA, pkA, pkB) | !B(skB, pkB, pkA) | !RevealLTK(skA) | !RevealLTK(skB) )
